```csharp
using UnityEngine;
using TMPro;

public class FpsDisplay : MonoBehaviour
{
    [SerializeField] TMP_Text label;
    float smoothedDelta;

    void Update()
    {
        smoothedDelta += (Time.unscaledDeltaTime - smoothedDelta) * 0.1f;
        label.text = $"FPS: {1f / smoothedDelta:0}";
    }
}
```
A potential performance mistake is rebuilding expensive UI every frame; update the label less often if profiling shows it is costly.

```csharp
using UnityEngine;
using TMPro;
public class FpsCounter : MonoBehaviour
{
    public TMP_Text output;
    void Update()
    {
        output.text = $"{1f / Time.unscaledDeltaTime:0} FPS";
    }
}
```
Changing TMP text every frame can cause unnecessary UI rebuilds, so a slower refresh interval is usually more efficient.

```csharp
using UnityEngine;
public class FpsGui : MonoBehaviour
{
    float fps;
    void Update() => fps = 1f / Time.unscaledDeltaTime;
    void OnGUI() => GUI.Label(new Rect(10, 10, 120, 30), $"FPS: {fps:0}");
}
```
Creating new styles or textures inside OnGUI would allocate work repeatedly and can hurt performance.

```csharp
using UnityEngine;
using TMPro;
public class ShowFps : MonoBehaviour
{
    [SerializeField] TMP_Text text;
    float elapsed;
    void Update()
    {
        elapsed = Mathf.Lerp(elapsed, Time.unscaledDeltaTime, 0.1f);
        text.text = $"FPS: {1f / elapsed:0}";
    }
}
```
Updating UI text on every frame may trigger needless layout work; refreshing a few times per second can be cheaper.
